1	import { ImageZoom } from "@likashefqet/react-native-image-zoom";
2	import { animateParallel, Block, Text } from "@prototyp/skeletor";
3	import { useAtom } from "jotai";
4	import { TimelineAtoms } from "modules/timeline/jotai";
5	import type { FC } from "react";
6	import { useCallback, useEffect, useRef, useState } from "react";
7	import { Dimensions, Modal, StyleSheet, TouchableOpacity } from "react-native";
8	import { Colors, TextSize } from "shared/styles";
9	import {
10	  cacheImage,
11	  getCachedImagePathByURL,
12	} from "shared/utils/image-caching";
13	import { Button } from "../button";
14	import { Loading } from "../loading";
15	
16	const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");
17	
18	const isLocalUri = (uri: string) => uri.startsWith("file://");
19	
20	export const ImageViewerModal: FC = () => {
21	  const [imageViewerUri, setImageViewerUri] = useAtom(
22	    TimelineAtoms.imageViewerUri,
23	  );
24	  const [localUri, setLocalUri] = useState<string | null>(null);
25	  const [isLoading, setIsLoading] = useState(true);
26	  const [hasError, setHasError] = useState(false);
27	  const [showControls, setShowControls] = useState(true);
28	  const visible = !!imageViewerUri;
29	
30	  const controlsAnimation = useRef(
31	    animateParallel(
32	      { translateY: [-120, 0], opacity: [0, 1] },
33	      { duration: 280 },
34	    ),
35	  ).current;
36	
37	  useEffect(() => {
38	    if (showControls) controlsAnimation.start();
39	    else controlsAnimation.reverse();
40	  }, [showControls]);
41	
42	  useEffect(() => {
43	    if (!imageViewerUri) return;
44	
45	    let cancelled = false;
46	    setLocalUri(null);
47	    setIsLoading(true);
48	    setHasError(false);
49	
50	    const load = async () => {
51	      try {
52	        if (isLocalUri(imageViewerUri)) {
53	          setLocalUri(imageViewerUri);
54	          return;
55	        }
56	
57	        await cacheImage(imageViewerUri);
58	        if (cancelled) return;
59	        setLocalUri(getCachedImagePathByURL(imageViewerUri));
60	      } catch {
61	        if (cancelled) return;
62	        setIsLoading(false);
63	        setHasError(true);
64	      }
65	    };
66	
67	    load();
68	
69	    return () => {
70	      cancelled = true;
71	    };
72	  }, [imageViewerUri]);
73	
74	  const onClose = useCallback(() => {
75	    setImageViewerUri(null);
76	    setLocalUri(null);
77	    setHasError(false);
78	    setIsLoading(true);
79	    setShowControls(true);
80	  }, [setImageViewerUri]);
81	
82	  const handleSingleTap = useCallback(() => {
83	    setShowControls((prev) => !prev);
84	  }, []);
85	
86	  const handleImageLoad = useCallback(() => {
87	    setIsLoading(false);
88	    setHasError(false);
89	  }, []);
90	
91	  const handleImageError = useCallback(() => {
92	    setIsLoading(false);
93	    setHasError(true);
94	  }, []);
95	
96	  const handleRetry = useCallback(async () => {
97	    if (!imageViewerUri) return;
98	    setLocalUri(null);
99	    setIsLoading(true);
100	    setHasError(false);
101	
102	    try {
103	      if (isLocalUri(imageViewerUri)) {
104	        setLocalUri(imageViewerUri);
105	        return;
106	      }
107	
108	      await cacheImage(imageViewerUri);
109	      setLocalUri(getCachedImagePathByURL(imageViewerUri));
110	    } catch {
111	      setIsLoading(false);
112	      setHasError(true);
113	    }
114	  }, [imageViewerUri]);
115	
116	  if (!visible) return null;
117	
118	  return (
119	    <Modal
120	      visible={visible}
121	      animationType="fade"
122	      statusBarTranslucent
123	      transparent
124	      onRequestClose={onClose}
125	    >
126	      <Block background={Colors.black} flex={1} justify="center" align="center">
127	        <Block
128	          absolute
129	          offsets={{ top: 0, left: 0, right: 0 }}
130	          zIndex={10}
131	          paddings={[56, 20, 16, 20]}
132	          align="flex-end"
133	          background={Colors.primary}
134	          animations={controlsAnimation.animations}
135	          pointerEvents={showControls ? "auto" : "none"}
136	        >
137	          <Button.Wrapper onPress={onClose}>
138	            <Text font="InstrumentSans-Semibold" color={Colors.white}>
139	              Close
140	            </Text>
141	          </Button.Wrapper>
142	        </Block>
143	
144	        <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
145	          {isLoading && !hasError && (
146	            <Block
147	              absolute
148	              width={SCREEN_WIDTH}
149	              height={SCREEN_HEIGHT}
150	              align="center"
151	              justify="center"
152	              zIndex={5}
153	              background={Colors.white10}
154	            >
155	              <Loading isFullScreen={false} />
156	            </Block>
157	          )}
158	
159	          {hasError ? (
160	            <Block
161	              width={SCREEN_WIDTH}
162	              height={SCREEN_HEIGHT}
163	              align="center"
164	              justify="center"
165	            >
166	              <Text color={Colors.white}>Failed to load image</Text>
167	              <TouchableOpacity
168	                onPress={handleRetry}
169	                style={styles.retryButton}
170	              >
171	                <Text size={TextSize.small} color={Colors.white}>
172	                  Tap to retry
173	                </Text>
174	              </TouchableOpacity>
175	            </Block>
176	          ) : localUri ? (
177	            <ImageZoom
178	              key={localUri}
179	              uri={localUri}
180	              minScale={1}
181	              maxScale={5}
182	              maxPanPointers={2}
183	              isPanEnabled
184	              isPinchEnabled
185	              isDoubleTapEnabled
186	              isSingleTapEnabled
187	              style={styles.image}
188	              onLoad={handleImageLoad}
189	              onError={handleImageError}
190	              onSingleTap={handleSingleTap}
191	            />
192	          ) : null}
193	        </Block>
194	      </Block>
195	    </Modal>
196	  );
197	};
198	
199	const styles = StyleSheet.create({
200	  container: {
201	    width: SCREEN_WIDTH,
202	    height: SCREEN_HEIGHT,
203	  },
204	  image: {
205	    width: SCREEN_WIDTH,
206	    height: SCREEN_HEIGHT,
207	  },
208	  retryButton: {
209	    marginTop: 12,
210	    paddingVertical: 8,
211	    paddingHorizontal: 16,
212	  },
213	});
