1	import { BottomSheetScrollView } from "@gorhom/bottom-sheet";
2	import { Block, Text, useAndroidBackHandler } from "@prototyp/skeletor";
3	import { MembershipState_Tags } from "@unomed/react-native-matrix-sdk";
4	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
5	import { NavigationContainerRef } from "modules/navigation/const";
6	import { RoomService } from "modules/room/service/RoomService";
7	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
8	import { Alert, Image, StyleSheet } from "react-native";
9	import Toast from "react-native-toast-message";
10	import { Button, Loading } from "shared/components";
11	import {
12	  AppBottomSheet,
13	  type AppBottomSheetRef,
14	} from "shared/components/bottom-sheet";
15	import { UserImage } from "shared/components/user-image/UserImage";
16	import { usePreventSwipeBack } from "shared/hooks";
17	import { Colors, TextSize } from "shared/styles";
18	import { offlineToastHelper } from "shared/utils";
19	
20	interface Props {
21	  isBottomSheetOpen: boolean;
22	  selectedMember: MemberDetailsPayload | null;
23	  roomId: string;
24	  onClose: () => void;
25	  onMemberAction?: (userId: string, action: "remove" | "ban" | "unban") => void;
26	}
27	
28	export const MemberDetailsBottomSheet: React.FC<Props> = ({
29	  isBottomSheetOpen,
30	  selectedMember,
31	  roomId,
32	  onClose,
33	  onMemberAction,
34	}) => {
35	  const sheetRef = useRef<AppBottomSheetRef>(null);
36	  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
37	  const [memberPowerLevel, setMemberPowerLevel] = useState<number | null>(null);
38	  const [kickLevel, setKickLevel] = useState(50);
39	  const [banLevel, setBanLevel] = useState(50);
40	
41	  const canRemove = useMemo(
42	    () =>
43	      userPowerLevel !== null &&
44	      memberPowerLevel !== null &&
45	      userPowerLevel >= kickLevel &&
46	      userPowerLevel > memberPowerLevel,
47	    [userPowerLevel, memberPowerLevel, kickLevel],
48	  );
49	  const canBan = useMemo(
50	    () =>
51	      userPowerLevel !== null &&
52	      memberPowerLevel !== null &&
53	      userPowerLevel >= banLevel &&
54	      userPowerLevel > memberPowerLevel,
55	    [userPowerLevel, memberPowerLevel, banLevel],
56	  );
57	  const isUser = useMemo(
58	    () => selectedMember?.userId === MatrixCore.instance?.userId(),
59	    [selectedMember],
60	  );
61	  const isBanned = useMemo(
62	    () => selectedMember?.membershipTag === MembershipState_Tags.Ban,
63	    [selectedMember],
64	  );
65	  const [activeAction, setActiveAction] = useState<
66	    "remove" | "ban" | "unban" | null
67	  >(null);
68	
69	  const handleClose = useCallback(() => {
70	    sheetRef.current?.close();
71	  }, []);
72	
73	  const handleViewProfile = useCallback(() => {
74	    sheetRef.current?.close();
75	
76	    if (isUser) {
77	      NavigationContainerRef.navigate("userProfile");
78	      return;
79	    }
80	    if (!selectedMember) return;
81	
82	    NavigationContainerRef.navigate("profile", {
83	      userId: selectedMember.userId,
84	      initialProfile: {
85	        userId: selectedMember.userId,
86	        displayName: selectedMember.displayName,
87	        avatarUrl: selectedMember.avatarUrl ?? undefined,
88	      },
89	    });
90	  }, [isUser, selectedMember]);
91	
92	  const handleConfirmAction = useCallback(
93	    async (action: "remove" | "ban" | "unban", reason: string) => {
94	      if (!selectedMember) return;
95	      try {
96	        setActiveAction(action);
97	
98	        onMemberAction?.(selectedMember.userId, action);
99	
100	        sheetRef.current?.close();
101	
102	        if (action === "ban") {
103	          await RoomService.banUserFromRoom(
104	            roomId,
105	            selectedMember.userId,
106	            reason || undefined,
107	          );
108	        } else if (action === "unban") {
109	          await RoomService.unbanUserFromRoom(
110	            roomId,
111	            selectedMember.userId,
112	            reason || undefined,
113	          );
114	        } else {
115	          await RoomService.removeUserFromRoom(
116	            roomId,
117	            selectedMember.userId,
118	            reason || undefined,
119	          );
120	        }
121	
122	        Toast.show({
123	          type: "success",
124	          text1: `User ${action === "ban" ? "banned" : action === "unban" ? "unbanned" : "removed"} successfully`,
125	        });
126	        NavigationContainerRef.goBack();
127	      } catch (error) {
128	        console.error(`Failed to ${action} user:`, error);
129	        offlineToastHelper(`Failed to ${action} user`);
130	      } finally {
131	        setActiveAction(null);
132	      }
133	    },
134	    [selectedMember, roomId, onMemberAction],
135	  );
136	
137	  const handleUserAction = useCallback(
138	    (action: "remove" | "ban" | "unban") => {
139	      if (!selectedMember) return;
140	
141	      const actionText = action === "ban" ? "banning" : "removing";
142	      const actionTitle = action === "ban" ? "Ban User" : "Remove User";
143	      const confirmButtonText =
144	        action === "ban" ? "Ban" : action === "unban" ? "Unban" : "Remove";
145	
146	      if (action === "unban") {
147	        Alert.alert(
148	          "Unban User",
149	          `Are you sure you want to unban ${selectedMember.displayName}?`,
150	          [
151	            {
152	              text: "Cancel",
153	              style: "cancel",
154	            },
155	            {
156	              text: "Unban",
157	              onPress: () => handleConfirmAction("unban", ""),
158	            },
159	          ],
160	        );
161	        return;
162	      }
163	
164	      Alert.prompt(
165	        actionTitle,
166	        `Enter a reason for ${actionText} ${selectedMember.displayName} (optional):`,
167	        [
168	          {
169	            text: "Cancel",
170	            style: "cancel",
171	          },
172	          {
173	            text: "Continue",
174	            onPress: (reason?: string) => {
175	              Alert.alert(
176	                "Are you sure?",
177	                `Are you sure you want to ${action} ${selectedMember.displayName} from this room?`,
178	                [
179	                  {
180	                    text: "Cancel",
181	                    style: "cancel",
182	                  },
183	                  {
184	                    text: confirmButtonText,
185	                    style: "destructive",
186	                    onPress: () => handleConfirmAction(action, reason || ""),
187	                  },
188	                ],
189	              );
190	            },
191	          },
192	        ],
193	        "plain-text",
194	      );
195	    },
196	    [selectedMember, handleConfirmAction],
197	  );
198	
199	  const handleRemoveUser = useCallback(
200	    () => handleUserAction("remove"),
201	    [handleUserAction],
202	  );
203	
204	  const handleBanUser = useCallback(
205	    () => handleUserAction("ban"),
206	    [handleUserAction],
207	  );
208	
209	  const handleUnbanUser = useCallback(
210	    () => handleUserAction("unban"),
211	    [handleUserAction],
212	  );
213	
214	  useAndroidBackHandler({
215	    handlePress: handleClose,
216	    enabled: isBottomSheetOpen,
217	    disableDefault: isBottomSheetOpen,
218	  });
219	
220	  usePreventSwipeBack(isBottomSheetOpen);
221	
222	  useEffect(() => {
223	    if (!isBottomSheetOpen || !selectedMember) return;
224	    RoomService.getUserPowerLevel(roomId)
225	      .then(setUserPowerLevel)
226	      .catch(console.error);
227	    RoomService.getUserPowerLevel(roomId, selectedMember.userId)
228	      .then(setMemberPowerLevel)
229	      .catch(console.error);
230	    RoomService.getRoomPowerLevels(roomId)
231	      .then((pl) => {
232	        if (!pl) return;
233	        const vals = pl.values();
234	        setKickLevel(Number(vals.kick));
235	        setBanLevel(Number(vals.ban));
236	      })
237	      .catch(console.error);
238	  }, [isBottomSheetOpen, selectedMember]);
239	
240	  if (!selectedMember) return null;
241	
242	  return (
243	    <>
244	      {activeAction && (
245	        <Loading
246	          text={
247	            activeAction === "ban"
248	              ? "Banning user..."
249	              : activeAction === "unban"
250	                ? "Unbanning user..."
251	                : "Removing user..."
252	          }
253	        />
254	      )}
255	      <AppBottomSheet
256	        ref={sheetRef}
257	        isOpen={isBottomSheetOpen}
258	        onClose={onClose}
259	        enableContentPanningGesture={false}
260	      >
261	        <BottomSheetScrollView scrollEnabled={false}>
