300	  public static sendMedia = async (
301	    roomId: string,
302	    asset: Asset,
303	    caption?: string,
304	  ) => {
305	    if (!asset?.uri) throw new Error("No uri found");
306	    const room = MatrixCore.getRoom(roomId);
307	    const timeline = await room.timeline();
308	    if (!timeline) throw new Error("Timeline not found");
309	
310	    const type = asset.type ?? "image/jpeg";
311	    const assetWidth = asset.width ?? 0;
312	    const assetHeight = asset.height ?? 0;
313	    const isVideo = type.startsWith("video/");
314	
315	    const fileSource: UploadParameters = {
316	      source: new UploadSource.File({
317	        filename: decodeURIComponent(asset.uri.replace("file://", "")),
318	      }),
319	      caption: caption || undefined,
320	      formattedCaption: undefined,
321	      mentions: undefined,
322	      inReplyTo: undefined,
323	    };
324	
325	    if (isVideo) {
326	      let thumbnailSource: UploadSource | undefined;
327	      let thumbnailWidth = assetWidth;
328	      let thumbnailHeight = assetHeight;
329	      let thumbnailSize = 0;
330	      let blurhash = "";
331	
332	      try {
333	        const thumbnail = await createThumbnail({
334	          url: asset.uri,
335	          timeStamp: 1000,
336	          format: "jpeg",
337	          maxWidth: 800,
338	          maxHeight: 600,
339	        });
340	
341	        const stat = await RNFS.stat(thumbnail.path);
342	        thumbnailWidth = thumbnail.width;
343	        thumbnailHeight = thumbnail.height;
344	        thumbnailSize = Number(stat.size);
345	        thumbnailSource = new UploadSource.File({ filename: thumbnail.path });
346	
347	        blurhash = await Blurhash.encode(`file://${thumbnail.path}`, 3, 3);
348	      } catch {
349	        // Thumbnail generation is best-effort — send without it if it fails
350	      }
351	
352	      // createThumbnail uses AVAssetImageGenerator with appliesPreferredTrackTransform=true,
353	      // so thumbnail dimensions are rotation-corrected. Derive video display dimensions
354	      // from thumbnail orientation: whichever raw dimension (1920 or 1080) belongs to
355	      // width vs height is determined by whether the thumbnail is landscape or portrait.
356	      const thumbIsLandscape = thumbnailWidth >= thumbnailHeight;
357	      const videoWidth = thumbIsLandscape
358	        ? Math.max(assetWidth, assetHeight)
359	        : Math.min(assetWidth, assetHeight);
360	      const videoHeight = thumbIsLandscape
361	        ? Math.min(assetWidth, assetHeight)
362	        : Math.max(assetWidth, assetHeight);
363	
364	      const videoHandle = timeline.sendVideo(fileSource, thumbnailSource, {
365	        height: BigInt(videoHeight),
366	        width: BigInt(videoWidth),
367	        mimetype: type,
368	        size: BigInt(asset.fileSize ?? 0),
369	        duration: asset.duration ? Math.round(asset.duration * 1000) : 0,
370	        thumbnailInfo: thumbnailSource
371	          ? {
372	              height: BigInt(thumbnailHeight),
373	              width: BigInt(thumbnailWidth),
374	              mimetype: "image/jpeg",
375	              size: BigInt(thumbnailSize),
376	            }
377	          : undefined,
378	        thumbnailSource: undefined,
379	        blurhash,
380	      });
381	      await videoHandle.join();
382	    } else {
383	      const imageHandle = timeline.sendImage(
384	        fileSource,
385	        new UploadSource.File({
386	          filename: decodeURIComponent(asset.uri.replace("file://", "")),
387	        }),
388	        {
389	          height: BigInt(assetHeight),
390	          width: BigInt(assetWidth),
391	          mimetype: type,
392	          size: BigInt(asset.fileSize ?? 0),
393	          thumbnailInfo: {
394	            height: BigInt(assetHeight),
395	            width: BigInt(assetWidth),
396	            mimetype: type,
397	            size: BigInt(asset.fileSize ?? 0),
398	          },
399	          thumbnailSource: undefined,
400	          blurhash: "",
401	          isAnimated: false,
402	        },
403	      );
404	      await imageHandle.join();
405	    }
406	  };
