589	  public static getTopReactions = (
590	    event: EventTimelineItem,
591	    limit = 3,
592	  ): TimelineReaction[] => {
593	    const normalized = this.getNormalizedReactions(event);
594	    return normalized
595	      .sort(
596	        (a, b) => b.count - a.count || b.latestTimestamp - a.latestTimestamp,
597	      )
598	      .slice(0, limit);
599	  };
600	
601	  private static getNormalizedReactions = (
602	    event: EventTimelineItem,
603	  ): TimelineReaction[] => {
604	    const reactionCandidates: unknown[] = [
605	      this.readValue(event, ["reactions"]),
606	      this.readValue(event, ["properties", "reactions"]),
607	      this.readValue(event, ["content", "inner", "reactions"]),
608	      this.readValue(event, ["content", "inner", "content", "reactions"]),
609	      this.readValue(event, [
610	        "content",
611	        "inner",
612	        "content",
613	        "kind",
614	        "inner",
615	        "content",
616	        "reactions",
617	      ]),
618	    ].filter(Boolean);
619	
620	    for (const candidate of reactionCandidates) {
621	      const parsed = this.parseReactionsCandidate(candidate);
622	      if (parsed.length) return parsed;
623	    }
624	
625	    return [];
626	  };
627	
628	  private static parseReactionsCandidate = (
629	    candidate: unknown,
630	  ): TimelineReaction[] => {
631	    if (!candidate) return [];
632	
633	    if (Array.isArray(candidate)) {
634	      return candidate
635	        .map((reaction) => this.parseSingleReaction(reaction))
636	        .filter((reaction): reaction is TimelineReaction => Boolean(reaction));
637	    }
638	
639	    if (candidate instanceof Map) {
640	      return Array.from(candidate.entries())
641	        .map(([key, value]) => this.parseEntryReaction(key, value))
642	        .filter((reaction): reaction is TimelineReaction => Boolean(reaction));
643	    }
644	
645	    if (typeof candidate === "object") {
646	      return Object.entries(candidate as Record<string, unknown>)
647	        .map(([key, value]) => this.parseEntryReaction(key, value))
648	        .filter((reaction): reaction is TimelineReaction => Boolean(reaction));
649	    }
650	
651	    return [];
652	  };
653	
654	  private static parseEntryReaction = (
655	    key: string,
656	    rawValue: unknown,
657	  ): TimelineReaction | null => {
658	    const currentUserId = MatrixCore.instance?.userId() ?? "";
659	    const normalizedKey = this.normalizeReactionKey(key);
660	    if (!normalizedKey) return null;
661	
662	    const detailedReaction = this.parseSingleReaction(rawValue);
663	    if (detailedReaction) {
664	      return {
665	        ...detailedReaction,
666	        key: normalizedKey,
667	        displayKey: String(detailedReaction.displayKey || normalizedKey).slice(
668	          0,
669	          16,
670	        ),
671	      };
672	    }
673	
674	    const senders = this.toSenders(rawValue, currentUserId);
675	    return {
676	      key: normalizedKey,
677	      displayKey: normalizedKey.slice(0, 16),
678	      count: senders.count,
679	      latestTimestamp: senders.latestTimestamp,
680	      isHighlighted: senders.isHighlighted,
681	      senders: senders.senders,
682	    };
683	  };
684	
685	  private static parseSingleReaction = (
686	    rawReaction: unknown,
687	  ): TimelineReaction | null => {
688	    if (!rawReaction || typeof rawReaction !== "object") return null;
689	    const currentUserId = MatrixCore.instance?.userId() ?? "";
690	
691	    const reaction = rawReaction as Record<string, unknown>;
692	    const normalizedKey = this.normalizeReactionKey(
693	      reaction.key ??
694	        reaction.displayKey ??
695	        reaction.emoji ??
696	        reaction.reaction,
697	    );
698	    if (!normalizedKey) return null;
699	
700	    const senders = this.toSenders(reaction.senders, currentUserId);
701	    const rawCount = Number(reaction.count);
702	    const count =
703	      Number.isFinite(rawCount) && rawCount > 0 ? rawCount : senders.count;
704	
705	    return {
706	      key: normalizedKey,
707	      displayKey: String(reaction.displayKey ?? normalizedKey).slice(0, 16),
708	      count,
709	      latestTimestamp: senders.latestTimestamp,
710	      isHighlighted:
711	        Boolean(reaction.isHighlighted) ||
712	        Boolean(reaction.highlighted) ||
713	        senders.isHighlighted,
714	      senders: senders.senders,
715	    };
716	  };
717	
718	  private static toSenders = (
719	    rawSenders: unknown,
720	    currentUserId: string,
721	  ): {
722	    count: number;
723	    latestTimestamp: number;
724	    isHighlighted: boolean;
725	    senders: TimelineReactionSender[];
726	  } => {
727	    if (!rawSenders)
728	      return {
729	        count: 1,
730	        latestTimestamp: 0,
731	        isHighlighted: false,
732	        senders: [],
733	      };
734	
735	    if (Array.isArray(rawSenders)) {
736	      const senders: TimelineReactionSender[] = rawSenders
737	        .map((sender) => ({
738	          userId: this.extractSenderUserId(sender),
739	          timestamp: this.extractTimestamp(sender),
740	        }))
741	        .filter((s) => s.userId);
742	      const latestTimestamp = senders.reduce(
743	        (max, s) => Math.max(max, s.timestamp),
744	        0,
745	      );
746	      const isHighlighted = senders.some((s) => s.userId === currentUserId);
747	      return {
748	        count: rawSenders.length || 1,
749	        latestTimestamp,
750	        isHighlighted,
751	        senders,
752	      };
753	    }
754	
755	    if (rawSenders instanceof Map) {
756	      const entries = Array.from(rawSenders.entries());
757	      const senders: TimelineReactionSender[] = entries
758	        .map(([senderId, sender]) => ({
759	          userId:
760	            typeof senderId === "string" && senderId
761	              ? senderId
762	              : this.extractSenderUserId(sender),
763	          timestamp: this.extractTimestamp(sender),
764	        }))
765	        .filter((s) => s.userId);
766	      const latestTimestamp = senders.reduce(
767	        (max, s) => Math.max(max, s.timestamp),
768	        0,
769	      );
770	      const isHighlighted = senders.some((s) => s.userId === currentUserId);
771	      return {
772	        count: entries.length || 1,
773	        latestTimestamp,
774	        isHighlighted,
775	        senders,
776	      };
777	    }
778	
779	    if (typeof rawSenders === "object") {
780	      const entries = Object.entries(rawSenders as Record<string, unknown>);
781	      const senders: TimelineReactionSender[] = entries
782	        .map(([senderId, sender]) => ({
783	          userId: senderId || this.extractSenderUserId(sender),
784	          timestamp: this.extractTimestamp(sender),
785	        }))
786	        .filter((s) => s.userId);
787	      const latestTimestamp = senders.reduce(
788	        (max, s) => Math.max(max, s.timestamp),
789	        0,
790	      );
791	      const isHighlighted = senders.some((s) => s.userId === currentUserId);
792	      return {
793	        count: entries.length || 1,
794	        latestTimestamp,
795	        isHighlighted,
796	        senders,
797	      };
798	    }
799	
800	    return { count: 1, latestTimestamp: 0, isHighlighted: false, senders: [] };
801	  };
802	
803	  private static extractTimestamp = (sender: unknown): number => {
804	    if (!sender || typeof sender !== "object") return 0;
805	    const record = sender as Record<string, unknown>;
806	    const rawTimestamp =
807	      record.timestamp ??
808	      record.ts ??
809	      this.readValue(record, ["inner", "timestamp"]);
810	    const timestamp = Number(rawTimestamp);
811	    return Number.isFinite(timestamp) ? timestamp : 0;
812	  };
813	
814	  private static extractSenderUserId = (sender: unknown): string => {
815	    if (!sender || typeof sender !== "object") return "";
816	    const record = sender as Record<string, unknown>;
817	    const rawUserId =
818	      record.userId ??
819	      record.senderId ??
820	      record.id ??
821	      this.readValue(record, ["inner", "userId"]);
822	    return typeof rawUserId === "string" ? rawUserId : "";
823	  };
824	
825	  private static normalizeReactionKey = (rawKey: unknown): string => {
826	    if (typeof rawKey !== "string") return "";
827	    return rawKey.trim();
828	  };
829	
830	  private static readValue = (source: unknown, path: string[]): unknown => {
831	    if (!source || typeof source !== "object") return undefined;
832	    let current: unknown = source;
833	    for (const segment of path) {
834	      if (!current || typeof current !== "object") return undefined;
835	      current = (current as Record<string, unknown>)[segment];
836	    }
837	    if (typeof current === "function") {
838	      try {
839	        return (current as () => unknown)();
840	      } catch {
841	        return undefined;
842	      }
843	    }
844	    return current;
845	  };
846	}
