7	
8	const SCREEN = Dimensions.get("screen");
9	
10	interface Props {
11	  avatarUrl: string | null | undefined;
12	  displayName: string | undefined;
13	  height?: number;
14	  width?: number;
15	  borderRadius?: number;
16	  downloadWidth?: number;
17	  downloadHeight?: number;
18	  onPress?: (uri: string) => void;
19	}
20	
21	export const UserImage: FC<Props> = ({
22	  avatarUrl,
23	  displayName,
24	  height = 32,
25	  width = 32,
26	  borderRadius = 48,
27	  downloadWidth = SCREEN.width,
28	  downloadHeight = SCREEN.height,
29	  onPress,
30	}) => {
31	  const [uri, setUri] = useState<string | null>(null);
32	  const uriRef = useRef<string | null>(null);
33	  const textSize = () => {
34	    if (height < 20) return TextSize.xtiny;
35	    if (height < 28) return TextSize.tiny;
36	    if (height < 32) return TextSize.small;
37	    if (height < 40) return TextSize.base;
38	    if (height < 48) return TextSize.medium;
39	    if (height < 56) return TextSize.large;
40	
41	    return TextSize.xlarge;
42	  };
43	
44	  const resolveAvatar = useCallback(async () => {
45	    if (!avatarUrl) return;
46	    const cached = await resolveMatrixImage({
47	      mxcUrl: avatarUrl,
48	      width,
49	      height,
50	    });
51	    if (!cached) return;
52	    uriRef.current = cached;
53	    setUri(cached);
54	  }, [avatarUrl, width, height]);
55	
56	  const handlePress = useCallback(async () => {
57	    if (!onPress || !avatarUrl) return;
58	    const largeUri = await resolveMatrixImage({
59	      mxcUrl: avatarUrl,
60	      width: downloadWidth,
61	      height: downloadHeight,
62	    });
63	    if (largeUri) onPress(largeUri);
64	  }, [onPress, avatarUrl, downloadWidth, downloadHeight]);
65	
66	  useEffect(() => {
67	    uriRef.current = null;
68	    setUri(null);
69	    resolveAvatar();
70	  }, [resolveAvatar]);
71	
72	  // Retry on foreground if the initial fetch failed
73	  useEffect(() => {
74	    const subscription = AppState.addEventListener("change", (state) => {
75	      if (state === "active" && !uriRef.current && avatarUrl) {
76	        resolveAvatar();
77	      }
78	    });
79	    return () => subscription.remove();
80	  }, [avatarUrl, resolveAvatar]);
81	
82	  if (uri) {
83	    const image = (
84	      <Image
85	        source={{ uri }}
86	        width={width}
87	        height={height}
88	        style={{
89	          width,
90	          height,
91	          borderRadius,
92	          borderWidth: 2,
93	          borderColor: Colors.white20,
94	        }}
95	      />
96	    );
97	
98	    if (onPress) {
99	      return <Button.Wrapper onPress={handlePress}>{image}</Button.Wrapper>;
100	    }
101	
102	    return image;
103	  }
104	
105	  return (
106	    <Block
107	      width={width}
108	      height={height}
109	      border={{
110	        borderWidth: 1,
111	        borderColor: Colors.white20,
112	        borderRadius,
113	      }}
114	      background={Colors.white20}
115	      align="center"
116	      justify="center"
117	    >
118	      <Text size={textSize()} color={Colors.white50}>
119	        {displayName?.charAt(0).toUpperCase()}
120	      </Text>
121	    </Block>
122	  );
123	};
