10	
11	interface Props {
12	  children: ReactNode;
13	  event: EventTimelineItem;
14	  content: string;
15	  onStart?: () => void;
16	  onFinalize?: () => void;
17	}
18	
19	export const MessageLongPressWrapper: React.FC<Props> = ({
20	  children,
21	  event,
22	  content,
23	  onStart,
24	  onFinalize,
25	}) => {
26	  const isFailedOwnEcho = event.isOwn && isFailedEcho(event);
27	  const shouldAttachLongPress = event.canBeRepliedTo || isFailedOwnEcho;
28	  const scale = useAnimateParallel(
29	    { scaleX: [1, 1.1], scaleY: [1, 1.1] },
30	    { duration: 700, easing: Easing.bezierFn(0.31, 0.04, 0.03, 1.04) },
31	  );
32	  const setLongPressPayload = useSetAtom(TimelineAtoms.longPressPayload);
33	
34	  const openSheet = useCallback(() => {
35	    const messageType = getMessageType(event);
36	    setLongPressPayload({ event, content, messageType });
37	  }, [content, event, setLongPressPayload]);
38	
39	  const vibrateEnd = useCallback(() => {
40	    Vibration.vibrate(1);
41	  }, []);
42	
43	  const longPress = Gesture.LongPress()
44	    .minDuration(500)
45	    .onBegin(() => {
46	      runOnJS(scale.start)();
47	      if (!onStart) return;
48	      runOnJS(onStart)();
49	    })
50	    .onStart(() => {
51	      runOnJS(openSheet)();
